insert into strada.agent_scripts (id,name,intent,steps) values ('s1','Bank return (R03) – pay not received','Pay not received – bank return','[{"id": "s1a", "name": "Greet and verify", "kind": "text", "text": "Hi {customer}, thank you for contacting Strada Payroll Support for {account}. I can see your employee ID ending {empId}. I''ll check the status of your most recent pay now."}, {"id": "s1b", "name": "Confirm bank return", "kind": "text", "text": "Your direct deposit for pay date {payDate} was returned by the bank with code R03 \u2013 no account or unable to locate. This usually means the routing or account number on file has a typo or the account was closed."}, {"id": "s1c", "name": "Offer live check", "kind": "text", "text": "I can issue a live check today for same-day courier, or re-issue the deposit once you confirm corrected bank details in Strada Pay. Which would you prefer?"}, {"id": "s1d", "name": "Update case", "kind": "macro", "action": "updateCase"}, {"id": "s1e", "name": "Link knowledge article", "kind": "macro", "action": "linkArticle"}, {"id": "s1f", "name": "Resolve case", "kind": "macro", "action": "resolveCase"}]'::jsonb);
insert into strada.agent_scripts (id,name,intent,steps) values ('s2','Incident – clustered bank returns','Pay group incident','[{"id": "s2a", "name": "Confirm scope", "kind": "text", "text": "Multiple employees in pay group {payGroup} reported missing deposits for {payDate}. Confirm the ACH file status with Treasury before replying to individual employees."}, {"id": "s2b", "name": "Notify client payroll lead", "kind": "text", "text": "Hi {clientLead}, we have identified an ACH return affecting {count} employees in {payGroup}. Root cause and remediation ETA to follow within 60 minutes. Affected employees will be contacted directly."}, {"id": "s2c", "name": "Escalate to Tier 3", "kind": "macro", "action": "updateCase"}, {"id": "s2d", "name": "Schedule client update", "kind": "macro", "action": "scheduleFollowUp"}]'::jsonb);
insert into strada.agent_scripts (id,name,intent,steps) values ('s3','W-2 / pay statement reissue','Document request','[{"id": "s3a", "name": "Confirm identity", "kind": "text", "text": "Hi {customer}, before I reissue your W-2 I need to confirm the last four digits of your SSN and your mailing address on file."}, {"id": "s3b", "name": "Reissue document", "kind": "text", "text": "Your {docYear} W-2 has been reissued to the Strada Pay document centre. It will be available for download within 15 minutes; a paper copy can be mailed on request."}, {"id": "s3c", "name": "Resolve case", "kind": "macro", "action": "resolveCase"}]'::jsonb);
insert into strada.agent_scripts (id,name,intent,steps) values ('s4','State move – withholding change','Tax withholding change','[{"id": "s4a", "name": "Confirm move details", "kind": "text", "text": "Hi {customer}, I see you moved from {fromState} to {toState} effective {moveDate}. I''ll walk you through updating your state withholding."}, {"id": "s4b", "name": "Explain forms", "kind": "text", "text": "Indiana requires form WH-4 for state and county withholding. Your Illinois IL-W-4 stops applying from the move date. Both can be submitted in Strada Pay \u203a Tax \u203a State withholding."}, {"id": "s4c", "name": "Link knowledge article", "kind": "macro", "action": "linkArticle"}, {"id": "s4d", "name": "Schedule follow-up", "kind": "macro", "action": "scheduleFollowUp"}, {"id": "s4e", "name": "Resolve case", "kind": "macro", "action": "resolveCase"}]'::jsonb);
insert into strada.agent_scripts (id,name,intent,steps) values ('s5','Garnishment correction','Garnishment deducted twice','[{"id": "s5a", "name": "Verify deduction", "kind": "text", "text": "Hi {customer}, I''m reviewing the deductions on your {payDate} pay statement. I can see two entries for the same child-support order {orderRef}."}, {"id": "s5b", "name": "Explain correction", "kind": "text", "text": "The duplicate was caused by the order being re-keyed when it was amended. We will refund the second deduction on your next pay and correct the order so it deducts once. The agency has not been over-remitted."}, {"id": "s5c", "name": "Update case", "kind": "macro", "action": "updateCase"}, {"id": "s5d", "name": "Resolve case", "kind": "macro", "action": "resolveCase"}]'::jsonb);
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01041','Handling an R03 bank return before the next cut-off','An R03 return means the receiving bank could not locate the account. Confirm the return on the ACH report, then offer the employee a live check or a re-deposit once corrected details are on file.',array['Check the ACH return report for the pay date; R03 = no account / unable to locate.','Verify the routing and account number the employee entered in Strada Pay. Most R03s are a transposed digit.','Offer a live check (same-day courier before 2 PM ET) or re-deposit after the employee corrects details.','Record the return code, pay date and remedy on the case. Do not re-send the original ACH file.']::text[],'Shared rules','Internal','Published',14,322,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '5 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01044','ACH return codes quick reference','R01 insufficient funds, R02 account closed, R03 no account, R04 invalid account number, R16 account frozen. Each code has a different employee conversation and remedy.',array['R01 – Insufficient funds (employer side; escalate to Treasury).','R02 – Account closed; employee must provide a new account.','R03 – No account / unable to locate; usually a typo.','R04 – Invalid account number structure.','R16 – Account frozen; employee must contact their bank.']::text[],'Shared rules','Internal','Published',3,210,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01052','Live check issuance and courier cut-offs','Live checks can be issued for employees whose deposit was returned. Courier cut-off is 2 PM ET for same-day delivery to the client site.',array['Request a live check from the Pay Distribution queue.','Same-day courier cut-off is 2 PM ET; after that, next business day.','The employee''s pay statement still shows the original pay date.']::text[],'Shared rules','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01060','Meridian Health Partners – BW-NUR pay calendar and contacts','Bi-weekly nursing pay group. Payroll lead Rachel Moreno. ACH file released T-2 by 11 AM ET.',array['Pay group BW-NUR, bi-weekly, Friday pay date.','Client payroll lead: Rachel Moreno.','ACH released T-2 11 AM ET; Treasury contact for returns: Meridian treasury desk.']::text[],'Meridian Health Partners KB','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01073','Incident handling: clustered bank returns in one pay group','Three or more returns in one pay group within an hour indicate a file-level problem, not individual typos. Open a parent case, link the employee cases as children and notify the client payroll lead.',array['Open a parent case with Type = Problem and Escalated = Yes.','Link each employee case as a child case.','Notify the client payroll lead within 60 minutes with scope and ETA.','Tier 3 verifies the ACH file; do not offer individual re-deposits until root cause is known.']::text[],'Shared rules','Internal','Published',9,97,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01081','Reissuing a W-2 or pay statement copy','Employees can download reissued W-2s from the Strada Pay document centre. Confirm identity (SSN last four and address) before reissuing.',array['Verify SSN last four and mailing address on file.','Reissue from Documents › Tax forms › Reissue; the copy is available within 15 minutes.','Paper copies are mailed within 5 business days on request.']::text[],'Shared rules','External','Published',22,540,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01085','Harbor Point Logistics – document retention and prior-year W-2s','Prior-year W-2s back to 2021 are available in the document centre; older years require a request to the client HR team.',array['Years 2021 onward: self-service download.','Older years: route to Harbor Point HR shared mailbox.']::text[],'Harbor Point Logistics KB','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01092','Mid-year state move: Illinois to Indiana withholding (WH-4)','Indiana uses form WH-4 for state and county withholding. The Illinois IL-W-4 stops applying from the move date. County of residence on 1 January sets the county rate for the year.',array['Employee submits WH-4 in Strada Pay › Tax › State withholding.','Set IL withholding end date = day before the move.','Indiana county tax is based on county of residence on 1 January; a mid-year move changes it next year.','Confirm with the employee whether the employer has IN nexus; if not, route to Tax & Withholding.']::text[],'Shared rules','External','Published',11,188,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01093','State withholding forms by state (2026)','Each state''s withholding certificate and whether the federal W-4 is accepted.',array['IL – IL-W-4','IN – WH-4','OH – IT 4','NJ – NJ-W4','WA – no state income tax']::text[],'Shared rules','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01101','Final pay timing rules by state','Final pay deadlines differ by state: California same day for involuntary termination, Illinois next scheduled payday, Ohio within 15 days or next payday.',array['CA – immediately on involuntary termination; 72 hours if the employee resigns without notice.','IL – next regular payday.','OH – earlier of next payday or 15 days.']::text[],'Shared rules','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01110','Correcting a duplicated garnishment deduction','A garnishment deducted twice is usually an amended order keyed as a new order. Refund the duplicate on the next pay, end-date the duplicate order and confirm the agency was not over-remitted.',array['Compare the two deduction lines: same order reference means a duplicate order, not a second order.','End-date the duplicate order with effective date = the pay period it first deducted.','Refund the duplicate amount on the next regular pay as a non-taxable adjustment.','Check remittance: if the agency received the duplicate, request a credit on the next remittance.']::text[],'Shared rules','Internal','Published',7,76,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '3 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01112','Garnishment limits under the CCPA','Ordinary garnishments are limited to 25% of disposable earnings; child-support orders up to 50–65% depending on dependants and arrears.',array['Ordinary creditor: lesser of 25% of disposable earnings or amount above 30 × federal minimum wage.','Child support: 50% (supporting another family) / 60% (not), +5% if more than 12 weeks in arrears.']::text[],'Shared rules','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01120','Benefits, FSA and 401(k) questions – route to Alight','Strada handles payroll only. Benefits enrolment, FSA reimbursements and 401(k) questions remained with Alight after the 2024 separation.',array['Confirm the question is about benefits, not a payroll deduction.','Transfer to the Misroute – Alight Benefits queue with the employee''s details.','Give the employee the Alight contact line.']::text[],'Shared rules','External','Published',3,410,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01131','Cascade Foods – weekly plant pay group WK-PLANT','Weekly pay group paid Thursday; time import from Kronos closes Tuesday 6 PM PT.',array['Pay date Thursday.','Kronos import closes Tuesday 6 PM PT; late approvals go to the next week.']::text[],'Cascade Foods KB','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.knowledge_articles (id,title,snippet,body,kb,audience,status,likes,views,modified) values ('KA-01140','Northbridge Retail Group – store pay group BW-STORE','Bi-weekly store group; many employees across IL/IN/WI with multi-state withholding.',array['Stores in IL, IN and WI.','Reciprocity: IL–WI, IN–WI; no IL–IN reciprocity.']::text[],'Northbridge Retail Group KB','Internal','Published',3,48,least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '12 days' + interval '10 hours 0 minutes')));
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,script_id,escalated_on,ai_updated,first_response_by,resolve_by,follow_up_by,summary,highlights) values ('Problem','US Payroll – ACH File','Four employees in Meridian Health Partners pay group BW-NUR reported missing deposits within 60 minutes. Treasury confirms 4 R03 returns on the ACH file released T-2. Root cause under investigation by Tier 3: suspected bank-details import from the Workday feed on 10/02 overwrote account numbers for records with leading zeros.','Priya Natarajan',true,true,array['KA-01073','KA-01060']::text[],array['type','escalated','description']::text[],false,'k2','CAS-10490-INC07','Incident: multiple BW-NUR bank returns on current pay date','c11','a2','Pay distribution','High','In Progress','Chat','q1',(now() - interval '41 minutes'),(now() - interval '6 minutes'),'Pay group incident','s2',(now() - interval '30 minutes'),true,(now() - interval '20 minutes'),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '17 hours 0 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '12 hours 0 minutes')),'Four Meridian Health Partners employees in pay group BW-NUR reported missing direct deposits for the current pay date within one hour. The Case Management Agent clustered the four employee cases under this incident and set Type = Problem, Escalated = Yes. Treasury has confirmed four R03 returns on the ACH file released two days before pay date. Tier 3 suspects the Workday bank-details import on 10/02 dropped leading zeros from account numbers. Client payroll lead Rachel Moreno has been notified with a 60-minute update commitment; a client update call is scheduled for 12:00.',array['4 employee cases (Whitfield, Ortega, Brown, Reilly) linked as child cases within 60 minutes.','Treasury confirmed 4 R03 returns on the BW-NUR ACH file.','Suspected root cause: Workday bank-details import on 10/02 dropped leading zeros.','Client payroll lead notified; update call at 12:00; Resolve By 5 PM today.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,resolved_on,intent,script_id,ai_created,ai_updated,resolution,first_response_by,resolve_by,summary,highlights) values ('Request','US Payroll – Tax Documents','Employee emailed asking for a copy of her 2025 W-2 for a mortgage application. Identity confirmed from the email address on file and SSN last four in the Strada Pay profile.','Priya Natarajan',false,true,array['KA-01081','KA-01085']::text[],array['title','subject','type','priority','product']::text[],false,'k6','CAS-10471-W2R2A','Request copy of 2025 W-2','c5','a1','Employee documents','Low','Resolved','Email','q5',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 12 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 31 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 31 minutes')),'Document request','s3',true,true,'W-2 reissued; reply sent',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '13 hours 0 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '9 hours 0 minutes')),'Anita Desai (Harbor Point Logistics) emailed requesting a copy of her 2025 W-2 for a mortgage application. The Case Management Agent created the case from the email and classified it as a document request. Identity was confirmed against the profile on file, the W-2 was reissued to the Strada Pay document centre and a reply email was sent with download instructions. The case was resolved autonomously 19 minutes after the email arrived with no representative action.',array['Case created from inbound email by the Case Management Agent.','2025 W-2 reissued to the document centre; reply email sent with download steps.','Resolved autonomously in 19 minutes; no representative action required.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,script_id,ai_updated,follow_up_by,first_response_by,resolve_by,summary,highlights) values ('Question','US Payroll – State Tax','Employee moved from Chicago, IL to Carmel, IN on 09/28. Last pay still withheld Illinois tax. Employee asks what forms are needed and whether Indiana county tax applies this year.','Priya Natarajan',false,true,array['KA-01092','KA-01093','KA-01140']::text[],array['subject','type','product']::text[],false,'k7','CAS-10478-WH4IN','Moved from Illinois to Indiana – state withholding not updated','c6','a3','Tax & withholding','Normal','Waiting for Details','Web','q3',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '14 hours 5 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '9 hours 40 minutes')),'Tax withholding change','s4',true,(date_trunc('day', now()) + interval '2 days' + interval '10 hours 0 minutes'),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '18 hours 0 minutes')),(date_trunc('day', now()) + interval '5 days' + interval '17 hours 0 minutes'),'Marcus Hill (Northbridge Retail Group, SM-HQ) moved from Illinois to Indiana on 09/28 and his most recent pay still withheld Illinois state tax. The Customer Intent Agent identified the intent as a mid-year state withholding change. He was told that Indiana requires form WH-4 and that Illinois withholding ends the day before the move; Indiana county tax is based on county of residence on 1 January, so it applies from next year. The WH-4 has not yet been submitted in Strada Pay. The Case Management Agent scheduled two follow-ups; the first is due in two days, after which the case closes automatically if the form is on file.',array['Moved IL → IN on 09/28; IL withholding still applied on the last pay.','Needs Indiana WH-4; IL-W-4 end-dated 09/27. County tax applies from next year.','Two automated follow-ups scheduled; auto-close when WH-4 is on file.','Article KA-01092 linked to the case.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,script_id,first_response_by,follow_up_by,resolve_by,summary,highlights) values ('Problem','US Payroll – Garnishments','Employee''s 10/10 pay statement shows two deductions of 312.00 for child-support order WA-CS-77821. Amended order received 10/01 was keyed as a new order instead of replacing the original.','Priya Natarajan',false,true,array['KA-01110','KA-01112']::text[],'{}'::text[],false,'k8','CAS-10483-GRN2X','Child-support garnishment deducted twice on 10/10 pay','c7','a4','Garnishments & deductions','High','Researching','Phone','q4',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '3 days' + interval '11 hours 20 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '8 hours 55 minutes')),'Garnishment deducted twice','s5',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '3 days' + interval '15 hours 0 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '15 hours 0 minutes')),(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),'Elena Petrova (Cascade Foods, WK-PLANT) called because her 10/10 pay statement shows two child-support deductions of 312.00 for the same order WA-CS-77821. Research shows the amended order received on 10/01 was keyed as a new order instead of replacing the original, so both deducted. The remedy is to end-date the duplicate order, refund 312.00 on the next weekly pay as a non-taxable adjustment and confirm with the Washington DCS that only one remittance was sent. The refund is approved; the remittance check with the agency is outstanding.',array['Two deductions of 312.00 for order WA-CS-77821 on the 10/10 pay.','Cause: amended order keyed as a new order on 10/01.','Refund of 312.00 approved for the next weekly pay; duplicate order end-dated.','Outstanding: confirm single remittance with Washington DCS.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,resolve_by,summary,highlights) values ('Question','Benefits (Alight)','Employee asked about an FSA reimbursement. FSA administration sits with Alight; transferred with employee details.','Priya Natarajan',false,true,array['KA-01120']::text[],'{}'::text[],false,'k9','CAS-10466-FSA01','FSA reimbursement not received','c8','a1','Benefits – misroute','Low','On Hold','Chat','q6',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '4 days' + interval '16 hours 2 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '4 days' + interval '16 hours 20 minutes')),'Benefits misroute',(date_trunc('day', now()) + interval '3 days' + interval '17 hours 0 minutes'),'Jordan Lee (Harbor Point Logistics) asked why an FSA reimbursement had not arrived. FSA administration is handled by Alight, not Strada Payroll. The case was transferred to the Misroute – Alight Benefits queue with the employee''s details and the employee was given the Alight contact line.',array['Benefits question, not payroll; transferred to Alight.','Employee given the Alight contact line.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,resolve_by,summary,highlights) values ('Question','US Payroll – Off-cycle','Store manager asks when the final pay for an associate terminated 10/13 must be issued under Illinois rules.','Priya Natarajan',false,true,array['KA-01101']::text[],'{}'::text[],false,'k10','CAS-10461-FPIL1','Final pay for terminated store associate – timing','c9','a3','Ongoing processing','Normal','In Progress','Email','q2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '5 days' + interval '10 hours 30 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '14 hours 10 minutes')),'Final pay timing',(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),'Samuel Okafor (Northbridge Retail Group, BW-STORE) emailed asking when final pay is due for an associate terminated on 10/13. Under Illinois rules final pay is due by the next regular payday, which is 10/24 for BW-STORE. An off-cycle check is not required unless the client requests it.',array['Illinois: final pay due by next regular payday (10/24).','Off-cycle only if the client requests it.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,resolve_by,summary,highlights) values ('Problem','US Payroll – Time Import','Weekly Kronos import for WK-PLANT rejected 14 records with unapproved time. Client payroll contact asked to approve before the Tuesday 6 PM cut-off.','Priya Natarajan',false,true,array['KA-01131']::text[],'{}'::text[],false,'k11','CAS-10455-TIME3','Kronos hours import rejected – 14 employees','c10','a4','Ongoing processing','Normal','In Progress','Email','q2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '6 days' + interval '8 hours 15 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '9 hours 0 minutes')),'Time import failure',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '18 hours 0 minutes')),'Grace Kim (Cascade Foods) reported that the weekly Kronos import for WK-PLANT rejected 14 records because time was unapproved. The client was asked to approve the records before the Tuesday 6 PM PT cut-off so they are included in Thursday''s pay.',array['14 records rejected: unapproved time.','Client to approve before Tuesday 6 PM PT.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,resolve_by,summary,highlights) values ('Request','US Payroll – Employee Data','Employee updated his address in Workday on 10/05 but the pay statement still shows the old address.','Priya Natarajan',false,true,'{}'::text[],'{}'::text[],false,'k12','CAS-10449-ADDR9','Address change not reflected on pay statement','c12','a1','Employee data','Low','In Progress','Web','q2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '8 days' + interval '13 hours 45 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '7 days' + interval '9 hours 0 minutes')),'Employee data change',(date_trunc('day', now()) + interval '2 days' + interval '17 hours 0 minutes'),'Victor Nguyen (Harbor Point Logistics, BW-OPS) updated his address in Workday on 10/05 but his pay statement still shows the old address. The Workday integration runs nightly; the change was confirmed in Strada Pay on 10/07 and will appear on the next statement.',array['Address updated in Workday 10/05; synced to Strada Pay 10/07.','Next pay statement will show the new address.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,modified_on,intent,script_id,ai_created,parent_id,first_response_by,resolve_by,follow_up_by,summary,highlights) values ('Problem','US Payroll – Direct Deposit','Employee reports nothing hit her account on pay date. ACH return report shows R03 for MHP-20417, amount 2,184.37. Account number on file ends 4471; employee states her account ends 4417.','Priya Natarajan',false,true,array['KA-01041','KA-01052']::text[],array['title','subject','priority','product','description']::text[],true,'k1','CAS-10492-R03M8','Pay not received – direct deposit returned (R03)','c1','a2','Pay distribution','High','In Progress','Chat','q1',(now() - interval '52 minutes'),(now() - interval '9 minutes'),'Pay not received – bank return','s1',true,'k2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '13 hours 0 minutes')),(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '16 hours 0 minutes')),'Dana Whitfield (Meridian Health Partners, pay group BW-NUR) reported that her direct deposit for the current pay date did not arrive. The ACH return report shows return code R03 (no account / unable to locate) for her deposit of 2,184.37. The account number on file ends 4471 while she confirms her account ends 4417, indicating a transposed digit entered during onboarding. She was offered a live check by same-day courier or a re-deposit once corrected details are saved in Strada Pay, and chose the live check. The case is linked to parent incident CAS-10490 because three other BW-NUR employees reported the same issue within the hour.',array['Direct deposit of 2,184.37 returned with code R03; account number on file ends 4471, employee''s ends 4417.','Employee chose a live check by same-day courier; courier cut-off is 2 PM ET.','Case linked as a child of incident CAS-10490 (BW-NUR cluster) by the Case Management Agent.','Follow-up due today at 4 PM to confirm delivery and corrected bank details.']::text[]);
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,parent_id,intent,script_id,ai_created,resolve_by,summary,highlights,modified_on) values ('Problem','US Payroll – Direct Deposit','Employee reports missing deposit on pay date. R03 return confirmed for MHP-20988, amount 1,962.10.','Priya Natarajan',false,true,array['KA-01041']::text[],array['title','subject','priority','description']::text[],true,'k3','CAS-10493-R03N1','Pay not received – direct deposit returned (R03)','c2','a2','Pay distribution','High','In Progress','Chat','q1',(now() - interval '47 minutes'),'k2','Pay not received – bank return','s1',true,(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),'Luis Ortega (Meridian Health Partners, BW-NUR) reported a missing direct deposit of 1,962.10 on the current pay date. The ACH return report shows R03. The case was created by the Case Management Agent from the chat and linked to incident CAS-10490.',array['R03 return confirmed for 1,962.10.','Linked to incident CAS-10490.','Awaiting root-cause confirmation before offering a remedy.']::text[],(now() - interval '47 minutes'));
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,parent_id,intent,script_id,ai_created,resolve_by,summary,highlights,modified_on) values ('Problem','US Payroll – Direct Deposit','Employee reports missing deposit on pay date. R03 return confirmed for MHP-21102, amount 2,310.55.','Priya Natarajan',false,true,array['KA-01041']::text[],array['title','subject','priority','description']::text[],true,'k4','CAS-10494-R03P4','Pay not received – direct deposit returned (R03)','c3','a2','Pay distribution','High','In Progress','Chat','q1',(now() - interval '44 minutes'),'k2','Pay not received – bank return','s1',true,(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),'Keisha Brown (Meridian Health Partners, BW-NUR) reported a missing direct deposit of 2,310.55. R03 return confirmed. Case created from chat by the Case Management Agent and linked to incident CAS-10490.',array['R03 return confirmed for 2,310.55.','Linked to incident CAS-10490.']::text[],(now() - interval '44 minutes'));
insert into strada.cases (type,product,description,owner,escalated,first_response_sent,article_ids,ai_fields,suggestions_pending,id,number,title,customer_id,account_id,subject,priority,status,origin,queue_id,created_on,parent_id,intent,script_id,ai_created,resolve_by,summary,highlights,modified_on) values ('Problem','US Payroll – Direct Deposit','Employee called about a missing deposit. R03 return confirmed for MHP-19876, amount 1,744.90.','Priya Natarajan',false,true,array['KA-01041']::text[],array['title','subject','priority','description']::text[],true,'k5','CAS-10495-R03Q9','Pay not received – direct deposit returned (R03)','c4','a2','Pay distribution','High','In Progress','Phone','q1',(now() - interval '38 minutes'),'k2','Pay not received – bank return','s1',true,(date_trunc('day', now()) + interval '1 days' + interval '17 hours 0 minutes'),'Tom Reilly (Meridian Health Partners, BW-NUR) called about a missing direct deposit of 1,744.90. R03 return confirmed. Case created from the voice conversation by the Case Management Agent and linked to incident CAS-10490.',array['R03 return confirmed for 1,744.90.','Linked to incident CAS-10490.']::text[],(now() - interval '38 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,transcript,modified_at) values (false,'t1','k1','chat','Dana Whitfield','Nothing hit my account',(now() - interval '52 minutes'),'Closed','[{"who": "Dana Whitfield", "text": "Hi, it''s pay day and nothing has hit my account. My colleagues got paid.", "at": "9:38 AM"}, {"who": "Strada Pay assistant", "text": "I''m sorry to hear that, Dana. I''ve verified your identity from the code we sent to your phone. Let me check the status of your deposit.", "at": "9:38 AM"}, {"who": "Strada Pay assistant", "text": "Your deposit of $2,184.37 was returned by your bank with code R03, which means the bank could not locate the account. The account number on file ends in 4471. Does that match your account?", "at": "9:39 AM"}, {"who": "Dana Whitfield", "text": "No! My account ends in 4417. Someone must have typed it wrong.", "at": "9:39 AM"}, {"who": "Strada Pay assistant", "text": "Thank you. I can issue a live check by same-day courier to the Meridian Health Partners site, or re-send the deposit once you correct the account number in Strada Pay. Which would you prefer?", "at": "9:40 AM"}, {"who": "Dana Whitfield", "text": "Live check please, I need the money today.", "at": "9:40 AM"}, {"who": "Strada Pay assistant", "text": "Done. A live check for $2,184.37 will be couriered today; you''ll get a text when it''s dispatched. I''ve created case CAS-10492 and a payroll specialist will follow up this afternoon.", "at": "9:41 AM"}]'::jsonb,(now() - interval '52 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t2','k1','note','Case Management Agent','Case Management Agent','Conversation summary',(now() - interval '50 minutes'),'Employee reported missing deposit on pay date. R03 return confirmed for $2,184.37. Account number on file ends 4471; employee confirms 4417. Employee chose live check by same-day courier. Case fields populated from the conversation.',(now() - interval '50 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t3','k1','autopost','Case Management Agent','Incident Clustering Agent','Case linked to parent CAS-10490',(now() - interval '35 minutes'),'Three further R03 returns detected in pay group BW-NUR within 60 minutes. This case was linked as a child of incident CAS-10490.',(now() - interval '35 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,due,modified_at) values (false,'t4','k1','task','Priya Natarajan','Confirm live check dispatched and corrected bank details saved',(now() - interval '9 minutes'),'Open',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '16 hours 0 minutes')),(now() - interval '9 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,subject,at,body,modified_at) values (false,'t5','k1','email','out','Priya Natarajan','Your pay for today – live check on its way',(now() - interval '9 minutes'),'Hi Dana, confirming that a live check for $2,184.37 is being couriered to the Meridian Health Partners site today. Please update your account number in Strada Pay › Pay › Direct deposit so future deposits go through. — Priya, Strada Payroll Support',(now() - interval '9 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t6','k2','autopost','Incident Clustering Agent','Incident Clustering Agent','Incident created from 4 related cases',(now() - interval '41 minutes'),'Four cases with intent ''Pay not received – bank return'' in pay group BW-NUR within 60 minutes. Parent case created; Type = Problem, Escalated = Yes.',(now() - interval '41 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,subject,at,body,modified_at) values (false,'t7','k2','email','out','Priya Natarajan','BW-NUR direct deposit returns – initial notification',(now() - interval '30 minutes'),'Hi Rachel, we have identified ACH returns affecting 4 employees in BW-NUR for today''s pay date. Treasury has confirmed the returns and Tier 3 is investigating the bank-details feed from 10/02. Root cause and remediation ETA within 60 minutes. Affected employees are being contacted directly and offered live checks. — Priya',(now() - interval '30 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,body,modified_at) values (false,'t8','k2','call','Rachel Moreno','Acknowledged notification; asked for list of affected employees',(now() - interval '22 minutes'),'Closed','Rachel acknowledged. Asked for the list of affected employees and confirmation that no other pay groups are affected. Confirmed BW-ADM file clean.',(now() - interval '22 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,due,modified_at) values (false,'t9','k2','appointment','Priya Natarajan','Client update call – BW-NUR incident',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '12 hours 0 minutes')),'Open',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '12 hours 30 minutes')),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '12 hours 0 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,body,modified_at) values (false,'t10','k2','note','Tier 3 – Ravi Menon','Root cause update',(now() - interval '6 minutes'),'Workday bank-details import on 10/02 dropped leading zeros on 4 account numbers (all starting 0). Fix: re-import with string typing; corrected details to Treasury for re-deposit on Monday. Live checks today for all 4.',(now() - interval '6 minutes'));
insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,transcript,modified_at) values (false,'t11','k3','chat','Luis Ortega','Missing pay today',(now() - interval '47 minutes'),'Closed','[{"who": "Luis Ortega", "text": "My pay didn''t come in today.", "at": "9:43 AM"}, {"who": "Strada Pay assistant", "text": "I''m sorry, Luis. Your deposit of $1,962.10 was returned with code R03. A specialist is looking into a wider issue affecting your pay group and will contact you within the hour.", "at": "9:44 AM"}]'::jsonb,(now() - interval '47 minutes'));
