insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,subject,at,body,modified_at) values (false,'t15','k6','email','in','Anita Desai','Copy of my 2025 W-2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 12 minutes')),'Hello, I need a copy of my 2025 W-2 for a mortgage application. Could you send it or tell me where to download it? Thanks, Anita Desai (HPL-30544)',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 12 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t16','k6','autopost','Case Management Agent','Case Management Agent','Case created from email',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 13 minutes')),'Case created from inbound email. Intent: Document request. Fields populated: Title, Subject, Type, Priority, Product.',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 13 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t17','k6','note','Case Management Agent','Case Management Agent','Identity confirmed; W-2 reissued',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 20 minutes')),'Email address matches profile on file. SSN last four verified against profile. 2025 W-2 reissued to the Strada Pay document centre (available within 15 minutes).',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 20 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,agent,subject,at,body,modified_at) values (true,'t18','k6','email','out','Strada Payroll Support','Case Management Agent','RE: Copy of my 2025 W-2',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 26 minutes')),'Hi Anita, your 2025 W-2 has been reissued and is available to download from Strada Pay › Documents › Tax forms. It will appear within 15 minutes. If you need a paper copy mailed to your address on file, reply to this email. — Strada Payroll Support',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 26 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t19','k6','autopost','Case Management Agent','Case Management Agent','Case resolved',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 31 minutes')),'Resolution: W-2 reissued; reply sent. Resolved autonomously.',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 31 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,subject,at,body,modified_at) values (false,'t20','k7','email','in','Marcus Hill','Moved to Indiana – still paying Illinois tax',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '14 hours 5 minutes')),'Hi, I moved from Chicago to Carmel, IN on Sept 28 and updated my address, but my last paycheck still took Illinois state tax. What do I need to do? Does Indiana county tax apply now?',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '14 hours 5 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,body,modified_at) values (true,'t21','k7','autopost','Customer Intent Agent','Customer Intent Agent','Intent identified: Tax withholding change (state move)',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '14 hours 6 minutes')),'Recommended article: KA-01092 Mid-year state move: Illinois to Indiana withholding (WH-4).',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '14 hours 6 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,direction,from_name,subject,at,body,modified_at) values (false,'t22','k7','email','out','Priya Natarajan','RE: Moved to Indiana – still paying Illinois tax',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '16 hours 40 minutes')),'Hi Marcus, thanks for letting us know. Indiana requires form WH-4 for state and county withholding; Illinois withholding will be end-dated 09/27. Please submit the WH-4 in Strada Pay › Tax › State withholding. Indiana county tax is based on your county of residence on 1 January, so it applies from next year. We''ll check back in a few days to confirm the form is on file. — Priya',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '16 hours 40 minutes')));
insert into strada.activities (ai_generated,id,case_id,type,from_name,agent,subject,at,status,due,modified_at) values (true,'t23','k7','task','Case Management Agent','Case Management Agent','Follow-up 1: confirm WH-4 submitted',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '9 hours 40 minutes')),'Open',(date_trunc('day', now()) + interval '2 days' + interval '10 hours 0 minutes'),least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '9 hours 40 minutes')));
