insert into strada.activities (ai_generated,id,case_id,type,from_name,subject,at,status,body,modified_at) values (false,'t25','k8','call','Elena Petrova','Two child-support deductions on my pay',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '3 days' + interval '11 hours 20 minutes')),'Closed','Employee reports two deductions of $312.00 on the 10/10 statement for order WA-CS-77821. Verified identity. Advised research needed; promised update within 2 business days.',least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '3 days' + interval '11 hours 20 minutes')));
