insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Voice agent','Thank you for calling Strada Payroll Support. To verify your identity I''ve sent a code to the mobile number on file. Please say the six digits.',(now() - interval '38 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Customer','Four two seven one nine three.',(now() - interval '37 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Voice agent','Thanks, Tom. How can I help today?',(now() - interval '36 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Customer','My pay didn''t come in this morning. Everyone else on my unit got paid.',(now() - interval '35 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Voice agent','I''m sorry about that. I can see your deposit of one thousand seven hundred forty-four dollars and ninety cents was returned by your bank with code R03, which means the bank could not locate the account. I''ve opened case CAS-10495 for you. I can issue a live check by courier today, or re-send the deposit once you correct your account number in Strada Pay.',(now() - interval '34 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Customer','I''d rather talk to a person about this.',(now() - interval '33 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','Voice agent','Of course. I''m transferring you to a payroll specialist now and passing along everything we''ve discussed. Please hold.',(now() - interval '32 minutes'));
insert into strada.transcript_lines (conversation_id,who,text,at) values ('cv1','System','Transferred to queue Pay Distribution with context. Waiting for a representative.',(now() - interval '31 minutes'));
