set search_path to strada, public;
truncate strada.transcript_lines, strada.conversations, strada.referrals, strada.alerts, strada.agent_runs, strada.events, strada.activities, strada.cases, strada.knowledge_articles, strada.agent_scripts, strada.contacts, strada.accounts, strada.queues restart identity cascade;
update strada.accounts set payroll_lead_contact_id='c11' where id='a2';
update strada.cases c set modified_on = v.m from (values ('k2', (now() - interval '6 minutes')),('k1', (now() - interval '9 minutes')),('k3', (now() - interval '47 minutes')),('k4', (now() - interval '44 minutes')),('k5', (now() - interval '38 minutes')),('k6', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '9 hours 31 minutes'))),('k7', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '9 hours 40 minutes'))),('k8', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '0 days' + interval '8 hours 55 minutes'))),('k9', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '4 days' + interval '16 hours 20 minutes'))),('k10', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '1 days' + interval '14 hours 10 minutes'))),('k11', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '2 days' + interval '9 hours 0 minutes'))),('k12', least(now() - interval '5 minutes', (date_trunc('day', now()) - interval '7 days' + interval '9 hours 0 minutes')))) as v(id, m) where c.id = v.id;
